#include <zephyr/drivers/adc.h>
#include <zephyr/ztest.h>
#include <zephyr/devicetree.h>

#define ADC_NODE DT_NODELABEL(adc_0)

#if !DT_NODE_EXISTS(ADC_NODE)
#error "ADC_NODE is not defined in the devicetree"
#endif

#define ADC_RESOLUTION 12
#define ADC_GAIN ADC_GAIN_1_3
#define ADC_REFERENCE ADC_REF_INTERNAL
#define ADC_ACQUISITION_TIME ADC_ACQ_TIME_DEFAULT

#define ADC_CHANNEL_ID 0

static const struct device *const adc_dev = DEVICE_DT_GET(ADC_NODE);

static struct adc_channel_cfg adc_channel_cfg = {
	.gain = ADC_GAIN,
	.reference = ADC_REFERENCE,
	.acquisition_time = ADC_ACQUISITION_TIME,
	.channel_id = ADC_CHANNEL_ID,
#ifdef CONFIG_ADC_NRFX_SAADC
	.input_positive = NRF_SAADC_INPUT_AIN0,
#endif
};

static int16_t sample_buffer[1];

static struct adc_sequence sequence = {
	.channels = BIT(ADC_CHANNEL_ID),
	.buffer = sample_buffer,
	.buffer_size = sizeof(sample_buffer),
	.resolution = ADC_RESOLUTION,
};

static void test_adc_setup(void)
{
	if (!device_is_ready(adc_dev)) {
		FAIL("ADC device is not ready");
	}

	int ret = adc_channel_setup(adc_dev, &adc_channel_cfg);

	if (ret < 0) {
		FAIL("ADC channel setup failed with error %d", ret);
	}
}

ZTEST_F(adc_api, test_adc_read_channel)
{
	int ret;

	ret = adc_read(adc_dev, &sequence);
	zassert_equal(ret, 0, "ADC read failed with error %d", ret);

	/* In a real application, you would process sample_buffer here. */
	/* For this test, we just ensure the read operation succeeded. */
}

ZTEST_F(adc_api, test_adc_invalid_channel)
{
	struct adc_channel_cfg invalid_channel_cfg = {
		.gain = ADC_GAIN,
		.reference = ADC_REFERENCE,
		.acquisition_time = ADC_ACQUISITION_TIME,
		.channel_id = 99, /* An invalid channel ID */
	};

	int ret = adc_channel_setup(adc_dev, &invalid_channel_cfg);
	zassert_not_equal(ret, 0, "ADC channel setup unexpectedly succeeded for invalid channel");
}

ZTEST_F(adc_api, test_adc_invalid_sequence)
{
	struct adc_sequence invalid_sequence = {
		.channels = BIT(ADC_CHANNEL_ID),
		.buffer = NULL, /* Invalid buffer */
		.buffer_size = 0,
		.resolution = ADC_RESOLUTION,
	};

	int ret = adc_read(adc_dev, &invalid_sequence);
	zassert_not_equal(ret, 0, "ADC read unexpectedly succeeded with invalid sequence");
}

ZTEST_SUITE(adc_api, NULL, test_adc_setup, NULL, NULL, NULL);
